import {C,$,esc,toast,save,on,modal,wait} from './studio-ui.js';
import {shotSpec,composeShot,importTemplate,importSchema,validateImport} from './shot-contract.js';
import {clone,uid,boardStale,validateRefs,invalidateChain,makeVideoSnapshot,boardReview,logJob,hub} from './workflow-store.js';
export function shotReady(s,sh){return !!s.final&&!boardStale(s)&&s.boardConfirmed===s.boardVersion&&sh.assets.every(a=>a.image&&a.confirmed)&&!validateRefs(sh).length}
export function independentReady(s,sh){return shotReady(s,sh)&&!sh.previousFrame}
export function specMarkup(s,sh){const g=shotSpec(s,sh),short={'720P':720,'1080P':1080,'4K':2160}[g.resolution],size=g.aspect==='1:1'?`${short}×${short}`:g.aspect==='16:9'?`${Math.round(short*16/9)}×${short}`:`${short}×${Math.round(short*16/9)}`;return `<div class="clip-specs"><span>${esc(g.model)}</span><span>${g.aspect} · ${size}</span><span>${g.duration}秒</span><span>${g.resolution}</span></div><button class="text-button" data-shot-settings="${sh.id}">调整本镜</button>${sh.videoTask?`<small class="helper">${esc(sh.videoTask)}</small>`:''}`}
export function boundMarkup(s,sh){const c=composeShot(s,sh);return `<div class="prompt-bindings"><details><summary>风格 · ${esc(c.style.name)} / 台词 ${c.dialogues.length} 段</summary><p>${esc(c.style.text)}</p>${c.dialogues.map(d=>`<p data-bound-line="${esc(d.id)}">${esc(d.speaker)}：${esc(d.text)}</p>`).join('')}<small>随当前风格和台词编译；生成时冻结为快照。</small></details></div>`}
function download(name,value){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function importDialog(){const s=C.s,base=s.boardVersion,script=s.final?.id;if(!script)return toast('请先确认剧本再导入分镜');if(s.chain.status==='running')return toast('请先暂停生成任务');let pending;const d=modal('导入分镜 JSON',`<p class="helper">导入为新版整表，旧表归档。仅导入内容和图片描述，不接受媒体URL或已完成状态；导入后需关联/生成参考图。</p><div class="row"><button class="button" id="download-board-template">下载JSON模板</button><button class="button" id="download-board-schema">下载格式规范</button></div><label class="field">选择JSON文件（≤1MB）<input id="board-json-file" type="file" accept=".json,application/json"></label><label class="field">或粘贴JSON<textarea id="board-json-input" rows="9"></textarea></label><p id="board-import-result" role="status"></p>`, '<button class="button" id="check-board-json">校验并预览</button><button class="button primary" id="apply-board-json" disabled>确认导入并刷新整表</button>');on('download-board-template',()=>download('分镜导入模板.json',importTemplate));on('download-board-schema',()=>download('分镜导入格式.schema.json',importSchema));const reset=()=>{pending=null;$('apply-board-json').disabled=true;$('board-import-result').textContent='内容已变化，请重新校验'};$('board-json-input').oninput=reset;$('board-json-file').onchange=async e=>{reset();const f=e.target.files[0];if(!f)return;if(f.size>1024*1024||!f.name.toLowerCase().endsWith('.json'))return $('board-import-result').textContent='请选择不超过1MB的JSON文件';try{$('board-json-input').value=await f.text()}catch{$('board-import-result').textContent='文件读取失败，请重新选择；原表未变'}};on('check-board-json',()=>{try{const text=$('board-json-input').value;if(new Blob([text]).size>1024*1024)throw Error('内容超过1MB');pending=clone(validateImport(JSON.parse(text)));$('board-import-result').textContent=`校验通过：${pending.shots.length}镜 / ${pending.shots.reduce((n,x)=>n+x.dialogues.length,0)}段台词 / ${pending.shots.reduce((n,x)=>n+x.duration,0)}秒。将替换当前${s.shots.length}镜，旧版归档；参考图需重新确认。`;$('apply-board-json').disabled=false}catch(e){pending=null;$('apply-board-json').disabled=true;$('board-import-result').textContent=e.message}});on('apply-board-json',()=>{if(!pending)return;if(s.boardVersion!==base||s.final?.id!==script||s.chain.status==='running')return toast('来源或分镜已变化，请关闭后重新导入');const before=clone(s);const ids=new Map();for(const sh of pending.shots)for(const x of [sh,...sh.assets,...sh.dialogues])ids.set(x.id,uid('import'));const shots=pending.shots.map(sh=>({...clone(sh),id:ids.get(sh.id),sourceImportId:sh.id,prompt:sh.prompt.replace(/@\[([^\]]+)\]/g,(_,id)=>`@[${ids.get(id)}]`),assets:sh.assets.map(a=>({...a,id:ids.get(a.id),version:1,image:null,confirmed:false})),dialogues:sh.dialogues.map(l=>({...l,id:ids.get(l.id)})),dialogue:sh.dialogues.map(l=>`${l.speaker}：${l.text}`).join('\n'),bindings:undefined,version:1,video:null,audio:null,previousFrame:null,videoStale:false}));s.projectElements??=[];for(const sh of shots)for(const a of sh.assets.filter(a=>['角色','场景','道具'].includes(a.kind))){a.entityId=uid('entity');s.projectElements.push({id:a.entityId,kind:a.kind,name:a.name,description:a.description,voice:'默认音色',threeViews:false,reference:null,image:null,version:1})}s.history.push({boardVersion:s.boardVersion,scriptId:s.boardScriptId,shots:clone(s.shots)});s.shots=shots;s.boardVersion++;s.boardScriptId=script;s.boardConfirmed=0;s.report=null;s.chain={mode:'independent',status:'idle',next:0,runId:null};s.importHistory??=[];s.importHistory.push({id:uid('import-batch'),format:pending.format,schemaVersion:1,idMap:Object.fromEntries(ids),at:Date.now()});boardReview(s);if(!save()){for(const key of Object.keys(s))if(!Object.hasOwn(before,key))delete s[key];Object.assign(s,before);$('board-import-result').textContent='保存失败，原分镜表已保留，请释放本地空间后重试';return}d.close();C.render();toast('分镜表已整体刷新，原版保留在历史中')});}
export function bindShotControls(){on('import-board-json',importDialog);document.querySelectorAll('[data-shot-settings]').forEach(b=>b.onclick=()=>{const s=C.s,sh=s.shots.find(x=>x.id===b.dataset.shotSettings),g=shotSpec(s,sh),h=hub(),models=[...new Set([g.model,s.generation?.model,s.modelDefaults?.video?.name,...Object.values(s.models||{}).filter(m=>m.capability==='video'||m.group==='video').map(m=>m.name)].filter(Boolean))];const opt=(items,v)=>items.map(x=>`<option ${x===v?'selected':''}>${esc(x)}</option>`).join('');const d=modal('本镜生成设置',`<p class="helper">默认继承项目，保存后仅覆盖本镜。已生成视频保留，标为待更新；依赖其尾帧的后镜也需更新。</p><label class="field">模型<select id="shot-model">${opt(models,g.model)}</select></label><div class="field-pair"><label class="field">比例<select id="shot-aspect">${opt(['9:16','16:9','1:1'],g.aspect)}</select></label><label class="field">分辨率<select id="shot-resolution">${opt(['720P','1080P','4K'],g.resolution)}</select></label></div><label class="field">时长（秒）<input id="shot-duration" type="number" min="0.1" max="600" step="0.1" value="${g.duration}"></label><p class="helper">原型参数仅示例；真实提交按模型能力限制可用规格。</p>`, '<button class="button" id="reset-shot-spec">恢复项目规格</button><button class="button primary" id="save-shot-spec">保存本镜</button>');function apply(reset){if(s.chain.status==='running')return toast('请先暂停生成任务');const duration=Number($('shot-duration').value);if(!Number.isFinite(duration)||duration<=0||duration>600)return toast('时长须大于0且不超过600秒');sh.generation=reset?{}:{model:$('shot-model').value,aspect:$('shot-aspect').value,resolution:$('shot-resolution').value};sh.duration=duration;sh.version++;invalidateChain(s,s.shots.indexOf(sh));save();d.close();C.render()}on('save-shot-spec',()=>apply(false));on('reset-shot-spec',()=>apply(true));});}
export async function runIndependent(start=0,one=false){const s=C.s,targets=(one?[s.shots[start]]:s.shots.filter(sh=>independentReady(s,sh)&&(!sh.video||sh.videoStale||sh.videoTask==='失败')));if(one?!shotReady(s,targets[0]):!targets.length)return toast('没有可提交镜头：请确认分镜与素材；并行批量还要求无尾帧依赖，已完成镜头会跳过');const skipped=s.shots.length-targets.length,runId=uid('parallel'),frozen=clone(s),jobs=targets.map(sh=>({sh,snapshot:makeVideoSnapshot(frozen,clone(sh),'independent',null)}));s.chain={...s.chain,mode:'independent',status:'running',runId,message:`提交${jobs.length}镜，${one?'本镜生成':`最多3镜并行；跳过${skipped}镜（已完成、缺素材或有尾帧依赖）`}`};for(const {sh} of jobs)sh.videoTask='排队';save();C.render();let cursor=0,failed=0;async function worker(){while(cursor<jobs.length&&s.chain.runId===runId){const {sh,snapshot}=jobs[cursor++];sh.videoTask='生成中';save();C.render();await wait(850);if(s.chain.runId!==runId)return;try{if(s.chain.failDemo){s.chain.failDemo=false;throw Error('单镜失败示例，其他独立镜头继续')}const video={id:uid('video'),kind:'demo',mode:'independent',snapshot};if(sh.video){sh.videoHistory??=[];sh.videoHistory.push(sh.video)}sh.video=video;sh.videoStale=sh.version!==snapshot.shotVersion||JSON.stringify(composeShot(s,sh).style)!==JSON.stringify(snapshot.style)||JSON.stringify(shotSpec(s,sh))!==JSON.stringify(snapshot.generationSpec);sh.videoTask=sh.videoStale?'输入已变':'成功';logJob(s,'video',video);for(const later of s.shots)if(later.previousFrame&&sh.videoHistory?.at(-1)?.id&&later.previousFrame.sourceVideoId===sh.videoHistory.at(-1).id){later.previousFrameStale=true;later.videoStale=!!later.video}}catch(e){failed++;sh.videoTask='失败';logJob(s,'video',{snapshot,error:e.message},'失败')}save();C.render()}}await Promise.all(Array.from({length:Math.min(3,jobs.length)},worker));if(s.chain.runId!==runId)return;s.chain.status=failed?'failed':'completed';s.chain.message=`${jobs.length-failed}镜完成，${failed}镜失败；独立镜头互不阻塞（本地演示，未提交云端）`;save();C.render();}
